  static const int DPM_PASSWORD_QUALITY_UNSPECIFIED = 0;

  /// < EAS(Exchange ActiveSync) requirement for simple password
  static const int DPM_PASSWORD_QUALITY_SIMPLE_PASSWORD = 1;

  /// < Some kind password is required, but doesn't care what it is
  static const int DPM_PASSWORD_QUALITY_SOMETHING = 16;

  /// < Containing at least numeric characters
  static const int DPM_PASSWORD_QUALITY_NUMERIC = 32;

  /// < Containing at least alphabetic (or other symbol) characters
  static const int DPM_PASSWORD_QUALITY_ALPHABETIC = 64;

  /// < Containing at least numeric and alphabetic characters
  static const int DPM_PASSWORD_QUALITY_ALPHANUMERIC = 128;
}

