  static const int DPM_PASSWORD_STATUS_NOT_CHANGED = 2;

  /// < Password change required
  static const int DPM_PASSWORD_STATUS_CHANGE_REQUIRED = 3;

  /// < Password Max Attempts Exceeded
  static const int DPM_PASSWORD_STATUS_MAX_ATTEMPTS_EXCEEDED = 4;

  /// < Password expired
  static const int DPM_PASSWORD_STATUS_EXPIRED = 5;

  /// < Device unlock failed by Password Recovery
  static const int DPM_PASSWORD_STATUS_RECOVERY_PASSWORD_FAILED = 6;

  /// < Device unlock succeeded by Password Recovery
  static const int DPM_PASSWORD_STATUS_RECOVERY_PASSWORD_SUCCEEDED = 7;

  /// < Password quality successfully changed
  static const int DPM_PASSWORD_STATUS_QUALITY_CHANGED = 8;

  /// < Password min_length successfully changed
  static const int DPM_PASSWORD_STATUS_MIN_LENGTH_CHANGED = 9;

  /// < Password complex_char successfully changed
  static const int DPM_PASSWORD_STATUS_COMPLEX_CHAR_CHANGED = 10;

  /// < Password pattern successfully changed
  static const int DPM_PASSWORD_STATUS_PATTERN_CHANGED = 11;
}

